  KEY `fk_opening_coverage` (`opening_coverage_id`,`stream_id`),
  CONSTRAINT `fk_coverage_run` FOREIGN KEY (`run_id`, `stream_id`) REFERENCES `account_history_sync_run` (`run_id`, `stream_id`),
  CONSTRAINT `fk_coverage_stream` FOREIGN KEY (`stream_id`) REFERENCES `account_history_stream` (`stream_id`),
  CONSTRAINT `fk_opening_coverage` FOREIGN KEY (`opening_coverage_id`, `stream_id`) REFERENCES `account_history_coverage` (`coverage_id`, `stream_id`),
  CONSTRAINT `fk_opening_transaction` FOREIGN KEY (`opening_transaction_id`, `stream_id`) REFERENCES `account_transaction` (`transaction_id`, `stream_id`),
  CONSTRAINT `ck_coverage_range` CHECK ((`range_from` <= `range_to`)),
  CONSTRAINT `ck_coverage_valid` CHECK ((`valid` in (0,1))),
  CONSTRAINT `ck_opening_evidence` CHECK ((((`opening_evidence` = _utf8mb4'NONE') and (`opening_balance` is null) and (`opening_transaction_id` is null) and (`opening_coverage_id` is null)) or ((`opening_evidence` = _utf8mb4'FIRST_TRANSACTION') and (`opening_balance` is not null) and (`opening_transaction_id` is not null) and (`opening_coverage_id` is null)) or ((`opening_evidence` = _utf8mb4'PREVIOUS_COVERAGE') and (`opening_balance` is not null) and (`opening_transaction_id` is null) and (`opening_coverage_id` is not null)) or ((`opening_evidence` = _utf8mb4'QA_SCENARIO') and (`opening_balance` is not null) and (`opening_transaction_id` is null) and (`opening_coverage_id` is null))))
