--
-- Table structure for table `account_history_stream`
--

DROP TABLE IF EXISTS `account_history_stream`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `account_history_stream` (
  `stream_id` bigint NOT NULL AUTO_INCREMENT,
  `linked_account_id` bigint NOT NULL,
  `user_id` bigint NOT NULL,
  `source` varchar(20) NOT NULL,
  `dataset_key` varchar(64) CHARACTER SET ascii COLLATE ascii_bin DEFAULT NULL,
  `generation` bigint NOT NULL DEFAULT '0',
  `active` tinyint(1) NOT NULL DEFAULT '0',
  `range_from` date DEFAULT NULL,
  `range_to` date DEFAULT NULL,
  `input_hash` varchar(64) CHARACTER SET ascii COLLATE ascii_general_ci DEFAULT NULL,
  `created_at` timestamp(6) NOT NULL,
  `updated_at` timestamp(6) NOT NULL,
  `version` bigint NOT NULL DEFAULT '0',
  PRIMARY KEY (`stream_id`),
  UNIQUE KEY `uk_history_source` (`linked_account_id`,`source`),
  KEY `fk_history_account` (`linked_account_id`,`user_id`),
  KEY `fk_history_dataset` (`dataset_key`,`user_id`),
  CONSTRAINT `fk_history_account` FOREIGN KEY (`linked_account_id`, `user_id`) REFERENCES `linked_account` (`linked_account_id`, `user_id`),
  CONSTRAINT `fk_history_dataset` FOREIGN KEY (`dataset_key`, `user_id`) REFERENCES `qa_seed_member` (`dataset_key`, `user_id`),
  CONSTRAINT `ck_history_active` CHECK ((`active` in (0,1))),
  CONSTRAINT `ck_history_generation` CHECK (((`generation` >= 0) and (`version` >= 0))),
  CONSTRAINT `ck_history_qa_range` CHECK (((`source` <> _utf8mb4'QA_SYNTHETIC') or ((`range_from` is not null) and (`range_to` is not null) and (`input_hash` is not null)))),
  CONSTRAINT `ck_history_range` CHECK ((((`range_from` is null) and (`range_to` is null)) or ((`range_from` is not null) and (`range_to` is not null) and (`range_from` <= `range_to`)))),
  CONSTRAINT `ck_history_source` CHECK ((((`source` = _utf8mb4'SSAFY') and (`dataset_key` is null)) or ((`source` = _utf8mb4'QA_SYNTHETIC') and (`dataset_key` is not null))))
) ENGINE=InnoDB AUTO_INCREMENT=23 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `account_history_stream`
--

