--
-- Table structure for table `account_history_sync_run`
--

DROP TABLE IF EXISTS `account_history_sync_run`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `account_history_sync_run` (
  `run_id` bigint NOT NULL AUTO_INCREMENT,
  `stream_id` bigint NOT NULL,
  `generation` bigint NOT NULL,
  `range_from` date NOT NULL,
  `range_to` date NOT NULL,
  `status` varchar(40) NOT NULL,
  `reported_count` bigint DEFAULT NULL,
  `received_count` bigint DEFAULT NULL,
  `queried_at` datetime(6) DEFAULT NULL,
  `created_at` timestamp(6) NOT NULL,
  `updated_at` timestamp(6) NOT NULL,
  `version` bigint NOT NULL DEFAULT '0',
  PRIMARY KEY (`run_id`),
  UNIQUE KEY `uk_sync_owner` (`run_id`,`stream_id`),
  KEY `ix_sync_stream` (`stream_id`,`run_id`),
  CONSTRAINT `fk_sync_stream` FOREIGN KEY (`stream_id`) REFERENCES `account_history_stream` (`stream_id`),
  CONSTRAINT `ck_sync_range` CHECK ((`range_from` <= `range_to`))
) ENGINE=InnoDB AUTO_INCREMENT=497 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
