--
-- Table structure for table `app_user`
--

DROP TABLE IF EXISTS `app_user`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `app_user` (
  `user_id` bigint NOT NULL AUTO_INCREMENT COMMENT 'YAMU 사용자 번호',
  `name` varchar(100) COLLATE utf8mb4_0900_bin DEFAULT NULL COMMENT '본인인증 이름; 가입 진행 중 미확보 가능',
  `birth_date` date DEFAULT NULL COMMENT '본인인증 생년월일',
  `phone_enc` varbinary(2048) DEFAULT NULL COMMENT '정규화한 휴대폰 번호의 암호화 봉투',
  `phone_hash` binary(32) DEFAULT NULL COMMENT '휴대폰 조회용 keyed HMAC-SHA-256; 정규화 후 계산',
  `pin_hash` varchar(255) COLLATE utf8mb4_0900_bin DEFAULT NULL COMMENT '솔트 포함 PIN 비밀번호 해시; 원문 금지',
  `pin_updated_at` timestamp(6) NULL DEFAULT NULL COMMENT 'UTC 마지막 PIN 설정·변경 시각',
  `payment_auto_select` tinyint(1) NOT NULL DEFAULT '1' COMMENT '결제 카드 자동 선택; 끄면 기본 카드로 결제(기본 카드가 있어야 끌 수 있음)',
  `auto_lock_seconds` int NOT NULL DEFAULT '60' COMMENT '앱을 떠난 뒤 다시 잠그기까지(초); 0·60·300',
  `barcode_auth_method` varchar(20) CHARACTER SET ascii COLLATE ascii_general_ci NOT NULL DEFAULT 'BIOMETRIC_OR_PIN' COMMENT '결제 코드를 열 때 인증 방식; BIOMETRIC_OR_PIN · PIN_ONLY',
  `identity_verified_at` timestamp(6) NULL DEFAULT NULL COMMENT 'UTC 본인인증 완료 시각',
  `ssafy_member_id` varchar(255) COLLATE utf8mb4_0900_bin DEFAULT NULL COMMENT '서버 생성 금융망 userId; y{랜덤 9자리}@yamu.app(19자, SSAFY 40자 제한), 최초 생성 후 재사용, 메일 인증 없음',
  `ssafy_user_key` varbinary(2048) DEFAULT NULL COMMENT '금융망 userKey 암호화 봉투; 평문 금지',
  `status` varchar(16) COLLATE utf8mb4_0900_bin NOT NULL DEFAULT 'PENDING' COMMENT 'PENDING / ACTIVE / WITHDRAWN',
  `deleted_at` timestamp(6) NULL DEFAULT NULL COMMENT 'UTC 탈퇴 시각; 실제 개인정보 파기와 별개',
  `withdrawn_name_hash` binary(32) DEFAULT NULL COMMENT '탈퇴 때 남긴 이름 조회용 keyed HMAC-SHA-256(앞뒤 공백 제거 후); 재가입 본인 확인용, 탈퇴 행에만',
  `notification_settings` json DEFAULT NULL COMMENT '알림 API의 유형별 설정; 미설정 NULL, 구조는 서비스 검증',
  `forecast_settings` json DEFAULT NULL COMMENT '잔고예보 API 설정; 미설정 NULL, 계좌·수입 참조는 서비스에서 소유권 검증',
  `created_at` timestamp(6) NOT NULL COMMENT 'UTC 생성 시각',
  `updated_at` timestamp(6) NOT NULL COMMENT 'UTC 수정 시각',
  `version` bigint NOT NULL DEFAULT '0' COMMENT 'JPA 낙관적 락 버전',
  PRIMARY KEY (`user_id`),
  UNIQUE KEY `uk_user_phone_birth` (`phone_hash`,`birth_date`),
  UNIQUE KEY `uk_user_ssafy_member` (`ssafy_member_id`),
  CONSTRAINT `ck_app_user_version` CHECK ((`version` >= 0)),
  CONSTRAINT `ck_user_active` CHECK (((`status` <> _utf8mb4'ACTIVE') or ((`name` is not null) and (`birth_date` is not null) and (`phone_enc` is not null) and (`phone_hash` is not null) and (`pin_hash` is not null) and (`pin_updated_at` is not null) and (`identity_verified_at` is not null)))),
  CONSTRAINT `ck_user_auto_lock_seconds` CHECK ((`auto_lock_seconds` in (0,60,300))),
  CONSTRAINT `ck_user_barcode_auth_method` CHECK ((`barcode_auth_method` in (_utf8mb4'BIOMETRIC_OR_PIN',_utf8mb4'PIN_ONLY'))),
  CONSTRAINT `ck_user_payment_auto_select` CHECK ((`payment_auto_select` in (0,1))),
  CONSTRAINT `ck_user_status` CHECK ((`status` in (_utf8mb4'PENDING',_utf8mb4'ACTIVE',_utf8mb4'WITHDRAWN'))),
  CONSTRAINT `ck_user_withdrawn` CHECK ((((`status` = _utf8mb4'WITHDRAWN') and (`deleted_at` is not null)) or ((`status` <> _utf8mb4'WITHDRAWN') and (`deleted_at` is null))))
) ENGINE=InnoDB AUTO_INCREMENT=17 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin COMMENT='사용자';
/*!40101 SET character_set_client = @saved_cs_client */;

