DROP TABLE IF EXISTS `benefit_application_group`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `benefit_application_group` (
  `benefit_application_group_id` bigint NOT NULL AUTO_INCREMENT,
  `card_product_id` bigint NOT NULL,
  `group_code` varchar(64) COLLATE utf8mb4_0900_bin NOT NULL,
  `policy_version` smallint NOT NULL,
  `application_mode` varchar(16) COLLATE utf8mb4_0900_bin NOT NULL,
  PRIMARY KEY (`benefit_application_group_id`),
  UNIQUE KEY `uk_application_group_version` (`card_product_id`,`group_code`,`policy_version`),
  UNIQUE KEY `uk_application_group_product` (`benefit_application_group_id`,`card_product_id`),
  CONSTRAINT `fk_application_product` FOREIGN KEY (`card_product_id`) REFERENCES `card_product` (`card_product_id`) ON DELETE RESTRICT,
  CONSTRAINT `ck_application_mode` CHECK ((`application_mode` in (_utf8mb4'STACK',_utf8mb4'MAX_ONE',_utf8mb4'PRIORITY_ONE'))),
  CONSTRAINT `ck_application_version` CHECK ((`policy_version` > 0))
) ENGINE=InnoDB AUTO_INCREMENT=5 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;
