  KEY `fk_application_member_group` (`benefit_application_group_id`,`card_product_id`),
  KEY `fk_application_member_benefit` (`card_benefit_id`,`card_product_id`),
  CONSTRAINT `fk_application_member_benefit` FOREIGN KEY (`card_benefit_id`, `card_product_id`) REFERENCES `card_benefit` (`card_benefit_id`, `card_product_id`) ON DELETE RESTRICT,
  CONSTRAINT `fk_application_member_group` FOREIGN KEY (`benefit_application_group_id`, `card_product_id`) REFERENCES `benefit_application_group` (`benefit_application_group_id`, `card_product_id`) ON DELETE RESTRICT,
  CONSTRAINT `ck_application_priority` CHECK (((`priority_order` is null) or (`priority_order` > 0)))
