--
-- Table structure for table `benefit_target`
--

DROP TABLE IF EXISTS `benefit_target`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `benefit_target` (
  `benefit_target_id` bigint NOT NULL AUTO_INCREMENT COMMENT '혜택 대상 번호',
  `card_benefit_id` bigint NOT NULL COMMENT '혜택 정책 버전',
  `target_type` varchar(16) COLLATE utf8mb4_0900_bin NOT NULL COMMENT 'ALL / BRAND / CATEGORY / CONDITION',
  `merchant_id` bigint DEFAULT NULL COMMENT 'BRAND 대상의 브랜드 단위 MERCHANT 참조',
  `target_value` varchar(128) COLLATE utf8mb4_0900_bin DEFAULT NULL COMMENT '업종 또는 거래 조건 코드; 예: CHANNEL:ONLINE, FACILITY:DEPARTMENT_STORE',
  `is_excluded` tinyint(1) NOT NULL DEFAULT '0' COMMENT '1이면 제외 조건',
  `target_key` varchar(128) COLLATE utf8mb4_0900_bin GENERATED ALWAYS AS ((case when (`target_type` = _utf8mb4'BRAND') then cast(`merchant_id` as char charset utf8mb4) when (`target_type` = _utf8mb4'ALL') then _utf8mb4'*' else `target_value` end)) STORED COMMENT 'NULL 중복을 피하는 대상 비교 키',
  `created_at` timestamp(6) NOT NULL COMMENT 'UTC 생성 시각',
  PRIMARY KEY (`benefit_target_id`),
  UNIQUE KEY `uk_target_benefit_pair` (`benefit_target_id`,`card_benefit_id`),
  UNIQUE KEY `uk_benefit_target` (`card_benefit_id`,`target_type`,`is_excluded`,`target_key`),
  KEY `fk_target_merchant` (`merchant_id`),
  CONSTRAINT `fk_target_benefit` FOREIGN KEY (`card_benefit_id`) REFERENCES `card_benefit` (`card_benefit_id`),
  CONSTRAINT `fk_target_merchant` FOREIGN KEY (`merchant_id`) REFERENCES `merchant` (`merchant_id`),
  CONSTRAINT `ck_target_excluded` CHECK ((`is_excluded` in (0,1))),
  CONSTRAINT `ck_target_exclusion_scope` CHECK (((`target_type` = _utf8mb4'CONDITION') or (`is_excluded` = 0))),
  CONSTRAINT `ck_target_shape` CHECK ((((`target_type` = _utf8mb4'BRAND') and (`merchant_id` is not null) and (`target_value` is null)) or ((`target_type` = _utf8mb4'ALL') and (`merchant_id` is null) and (`target_value` is null)) or ((`target_type` in (_utf8mb4'CATEGORY',_utf8mb4'CONDITION',_utf8mb4'PURCHASE_ITEM')) and (`merchant_id` is null) and (`target_value` is not null))))
) ENGINE=InnoDB AUTO_INCREMENT=1344 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin COMMENT='혜택 적용·제외 대상';
/*!40101 SET character_set_client = @saved_cs_client */;

