  CONSTRAINT `ck_discount_amount` CHECK ((`amount` > 0))
) ENGINE=InnoDB AUTO_INCREMENT=46 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin COMMENT='회차별 청구할인 배분';
