DROP TABLE IF EXISTS `card_benefit`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `card_benefit` (
  `card_benefit_id` bigint NOT NULL AUTO_INCREMENT COMMENT '혜택 정책 버전 번호',
  `card_product_id` bigint NOT NULL COMMENT '대상 상품',
  `benefit_code` varchar(64) COLLATE utf8mb4_0900_bin NOT NULL COMMENT '버전 간 유지되는 YAMU 논리 혜택 코드',
  `policy_version` smallint NOT NULL COMMENT '정책 버전 1~32767; JPA 락 버전과 별개',
  `benefit_name` varchar(150) COLLATE utf8mb4_0900_bin NOT NULL COMMENT '혜택 이름',
  `benefit_type` varchar(16) COLLATE utf8mb4_0900_bin NOT NULL COMMENT 'DISCOUNT / CASHBACK / POINT',
  `calculation_type` varchar(16) COLLATE utf8mb4_0900_bin NOT NULL COMMENT 'RATE / FIXED',
  `rate` decimal(9,6) DEFAULT NULL COMMENT '0~1 비율; RATE일 때 필수',
  `fixed_value` decimal(19,6) DEFAULT NULL COMMENT '정액 혜택값; 원화 또는 포인트',
  `value_unit` varchar(16) COLLATE utf8mb4_0900_bin NOT NULL COMMENT 'KRW / POINT',
  `point_krw_rate` decimal(19,6) DEFAULT NULL COMMENT '공식 포인트 원화 환산율; 미확인 NULL',
  `application_timing` varchar(32) COLLATE utf8mb4_0900_bin DEFAULT NULL COMMENT 'AT_APPROVAL: 승인 시 즉시 할인 / AT_BILLING: 청구 시 할인 / AFTER_BILLING: 청구 후 캐시백 / POINT_ACCRUAL: 포인트 적립; 미확인 NULL',
  `rounding_mode` varchar(16) COLLATE utf8mb4_0900_bin DEFAULT NULL COMMENT 'DOWN / HALF_UP / HALF_EVEN / UP; 약관 미확인 NULL',
  `rounding_unit` smallint DEFAULT NULL COMMENT '절사·반올림 결과 단위; 1이면 1원 또는 1포인트, 미확인 NULL',
  `rounding_stage` varchar(32) COLLATE utf8mb4_0900_bin DEFAULT NULL COMMENT 'PER_TRANSACTION: 거래별 소수점 처리 / AFTER_AGGREGATION: 합산 후 소수점 처리; 미확인 NULL',
  `min_payment_amount` bigint NOT NULL DEFAULT '0' COMMENT '최소 결제 금액',
  `min_performance_amount` bigint NOT NULL DEFAULT '0' COMMENT '최소 전월 실적',
  `valid_from` date DEFAULT NULL COMMENT '공식 적용 시작일; 한국 날짜, 포함, 미확인 NULL',
  `valid_until` date DEFAULT NULL COMMENT '공식 적용 종료일; 한국 날짜, 미포함, 종료일 미확인·미정 NULL',
  `conditions_json` json DEFAULT NULL COMMENT '허용 키 weekdays/startTime/endTime; 한국 시각, 시작 포함·끝 미포함, 자정 넘김 지원; 구조·계산은 서비스 검증',
  `terms_url` varchar(1000) COLLATE utf8mb4_0900_bin DEFAULT NULL COMMENT '이 버전의 원본 약관',
  `created_at` timestamp(6) NOT NULL COMMENT 'UTC 생성 시각',
  `fallback_benefit_id` bigint DEFAULT NULL,
  `fallback_mode` varchar(32) COLLATE utf8mb4_0900_bin DEFAULT NULL,
  PRIMARY KEY (`card_benefit_id`),
  UNIQUE KEY `uk_benefit_version` (`card_product_id`,`benefit_code`,`policy_version`),
  UNIQUE KEY `uk_benefit_product` (`card_benefit_id`,`card_product_id`),
  KEY `ix_benefit_effective` (`card_product_id`,`valid_from`,`valid_until`),
  KEY `fk_fallback_product` (`fallback_benefit_id`,`card_product_id`),
  CONSTRAINT `fk_benefit_product` FOREIGN KEY (`card_product_id`) REFERENCES `card_product` (`card_product_id`),
  CONSTRAINT `fk_fallback_product` FOREIGN KEY (`fallback_benefit_id`, `card_product_id`) REFERENCES `card_benefit` (`card_benefit_id`, `card_product_id`),
  CONSTRAINT `ck_benefit_amounts` CHECK (((`min_payment_amount` >= 0) and (`min_performance_amount` >= 0))),
  CONSTRAINT `ck_benefit_calc` CHECK ((((`calculation_type` = _utf8mb4'RATE') and (`rate` is not null) and (`rate` between 0 and 1) and (`fixed_value` is null)) or ((`calculation_type` = _utf8mb4'FIXED') and (`fixed_value` is not null) and (`fixed_value` >= 0) and (`rate` is null)))),
  CONSTRAINT `ck_benefit_dates` CHECK (((`valid_from` is null) or (`valid_until` is null) or (`valid_until` > `valid_from`))),
  CONSTRAINT `ck_benefit_exchange` CHECK (((`point_krw_rate` is null) or (`point_krw_rate` > 0))),
  CONSTRAINT `ck_benefit_fallback` CHECK ((((`fallback_benefit_id` is null) and (`fallback_mode` is null)) or ((`fallback_benefit_id` is not null) and (`fallback_mode` is not null) and (`fallback_mode` = _utf8mb4'EXCESS_PAYMENT_AMOUNT')))),
  CONSTRAINT `ck_benefit_rounding` CHECK (((`rounding_mode` is null) or (`rounding_mode` in (_utf8mb4'DOWN',_utf8mb4'HALF_UP',_utf8mb4'HALF_EVEN',_utf8mb4'UP')))),
  CONSTRAINT `ck_benefit_rounding_stage` CHECK (((`rounding_stage` is null) or (`rounding_stage` in (_utf8mb4'PER_TRANSACTION',_utf8mb4'AFTER_AGGREGATION')))),
  CONSTRAINT `ck_benefit_rounding_unit` CHECK (((`rounding_unit` is null) or (`rounding_unit` > 0))),
  CONSTRAINT `ck_benefit_type` CHECK ((`benefit_type` in (_utf8mb4'DISCOUNT',_utf8mb4'CASHBACK',_utf8mb4'POINT'))),
  CONSTRAINT `ck_benefit_unit` CHECK ((`value_unit` in (_utf8mb4'KRW',_utf8mb4'POINT'))),
  CONSTRAINT `ck_benefit_version` CHECK ((`policy_version` > 0))
) ENGINE=InnoDB AUTO_INCREMENT=94 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin COMMENT='혜택 정책 버전';
/*!40101 SET character_set_client = @saved_cs_client */;

