--
-- Table structure for table `card_bill`
--

DROP TABLE IF EXISTS `card_bill`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `card_bill` (
  `card_bill_id` bigint NOT NULL AUTO_INCREMENT COMMENT '카드 청구서 번호',
  `user_id` bigint NOT NULL COMMENT '청구 사용자',
  `user_card_id` bigint NOT NULL COMMENT '청구 카드',
  `linked_account_id` bigint DEFAULT NULL COMMENT '청구 확정 당시 출금 계좌',
  `billing_month` date NOT NULL COMMENT '한국 기준 청구 월의 1일',
  `period_start` date NOT NULL COMMENT '이용기간 시작; 포함',
  `period_end` date NOT NULL COMMENT '이용기간 마감; 포함',
  `withdrawal_date` date NOT NULL COMMENT '한국 업무 날짜 출금 예정일',
  `status` varchar(24) COLLATE utf8mb4_0900_bin NOT NULL COMMENT '청구·출금 처리 상태 코드',
  `confirmed_amount` bigint DEFAULT NULL COMMENT '확정 원본 청구액; 확정 후 덮어쓰지 않음',
  `paid_amount` bigint NOT NULL DEFAULT '0' COMMENT '확인된 출금 금액',
  `canceled_unpaid_principal` bigint NOT NULL DEFAULT '0' COMMENT '취소로 납부 대상에서 제외한 미납 원금',
  `confirmed_at` timestamp(6) NULL DEFAULT NULL COMMENT 'UTC 청구 확정 시각',
  `paid_at` timestamp(6) NULL DEFAULT NULL COMMENT 'UTC 출금 성공 확인 시각',
  `failed_at` timestamp(6) NULL DEFAULT NULL COMMENT 'UTC 출금 실패 확인 시각',
  `withdrawal_retried_at` timestamp(6) NULL DEFAULT NULL COMMENT 'UTC 첫 출금이 처리되지 않았다고 보고 새 요청 번호로 다시 보낸 시각; 다시 보내지 않았으면 NULL',
  `fin_request_no` char(20) CHARACTER SET ascii COLLATE ascii_bin DEFAULT NULL COMMENT '은행 출금 institutionTransactionUniqueNo; YYYYMMDD+HHMMSS+일련번호 6자리; 서버 공통 Redis INCR 채번, 금융망 새 호출마다 새 번호',
  `fin_transaction_no` varchar(128) CHARACTER SET ascii COLLATE ascii_bin DEFAULT NULL COMMENT '확인한 은행 출금 거래 참조',
  `created_at` timestamp(6) NOT NULL COMMENT 'UTC 생성 시각',
  `updated_at` timestamp(6) NOT NULL COMMENT 'UTC 수정 시각',
  `version` bigint NOT NULL DEFAULT '0' COMMENT 'JPA 낙관적 락 버전',
  PRIMARY KEY (`card_bill_id`),
  UNIQUE KEY `uk_bill_card_month` (`user_card_id`,`billing_month`),
  UNIQUE KEY `uk_bill_card_owner` (`card_bill_id`,`user_id`,`user_card_id`),
  KEY `ix_bill_due` (`status`,`withdrawal_date`),
  KEY `ix_bill_card_owner` (`user_card_id`,`user_id`),
  KEY `ix_bill_account_owner` (`linked_account_id`,`user_id`),
  CONSTRAINT `fk_bill_account_owner` FOREIGN KEY (`linked_account_id`, `user_id`) REFERENCES `linked_account` (`linked_account_id`, `user_id`),
  CONSTRAINT `fk_bill_card_owner` FOREIGN KEY (`user_card_id`, `user_id`) REFERENCES `user_card` (`user_card_id`, `user_id`),
  CONSTRAINT `ck_bill_amounts` CHECK ((((`confirmed_amount` is null) or (`confirmed_amount` >= 0)) and (`paid_amount` >= 0) and (`canceled_unpaid_principal` >= 0) and ((`confirmed_amount` is null) or (`canceled_unpaid_principal` <= `confirmed_amount`)))),
  CONSTRAINT `ck_bill_confirmed` CHECK (((`confirmed_at` is null) or ((`confirmed_amount` is not null) and (`linked_account_id` is not null)))),
  CONSTRAINT `ck_bill_month` CHECK ((dayofmonth(`billing_month`) = 1)),
  CONSTRAINT `ck_bill_paid` CHECK (((`paid_at` is null) or ((`confirmed_at` is not null) and (`linked_account_id` is not null)))),
  CONSTRAINT `ck_bill_period` CHECK ((`period_end` >= `period_start`)),
  CONSTRAINT `ck_card_bill_version` CHECK ((`version` >= 0))
) ENGINE=InnoDB AUTO_INCREMENT=94 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin COMMENT='카드 월별 청구서';
