--
-- Table structure for table `card_monthly_performance`
--

DROP TABLE IF EXISTS `card_monthly_performance`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `card_monthly_performance` (
  `card_monthly_performance_id` bigint NOT NULL AUTO_INCREMENT COMMENT '월간 실적 번호',
  `user_card_id` bigint NOT NULL COMMENT '보유 카드',
  `performance_month` date NOT NULL COMMENT '실적 집계 대상 월(한국 기준); 2026년 10월은 2026-10-01, 1일은 월 표시용이며 실제 결제일이 아님',
  `recognized_amount` bigint NOT NULL COMMENT '확정된 월간 실적 합계; 신규 카드·확인된 무거래는 0, seed 누락·초기화 실패는 등록 실패',
  `created_at` timestamp(6) NOT NULL COMMENT 'UTC 생성 시각',
  `updated_at` timestamp(6) NOT NULL COMMENT 'UTC 수정 시각',
  `version` bigint NOT NULL DEFAULT '0' COMMENT 'JPA 낙관적 락 버전',
  PRIMARY KEY (`card_monthly_performance_id`),
  UNIQUE KEY `uk_performance_card_month` (`user_card_id`,`performance_month`),
  CONSTRAINT `fk_performance_card` FOREIGN KEY (`user_card_id`) REFERENCES `user_card` (`user_card_id`),
  CONSTRAINT `ck_card_monthly_performance_version` CHECK ((`version` >= 0)),
  CONSTRAINT `ck_performance_amount` CHECK ((`recognized_amount` >= 0)),
  CONSTRAINT `ck_performance_month` CHECK ((dayofmonth(`performance_month`) = 1))
) ENGINE=InnoDB AUTO_INCREMENT=317 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin COMMENT='카드별 월간 실적';
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `card_monthly_performance`
--

LOCK TABLES `card_monthly_performance` WRITE;
