--
-- Table structure for table `card_product`
--

DROP TABLE IF EXISTS `card_product`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `card_product` (
  `card_product_id` bigint NOT NULL AUTO_INCREMENT COMMENT 'YAMU 내부 상품 번호; 외부 상품 코드 아님',
  `issuer_code` varchar(32) COLLATE utf8mb4_0900_bin NOT NULL COMMENT 'YAMU 카드사 코드',
  `product_name` varchar(150) COLLATE utf8mb4_0900_bin NOT NULL COMMENT '세대·에디션을 포함해 구분한 상품명',
  `card_type` varchar(16) COLLATE utf8mb4_0900_bin NOT NULL COMMENT 'CREDIT / CHECK',
  `billing_cutoff_days` smallint DEFAULT NULL COMMENT '결제일에서 뺄 일수; 신용카드 정책 자료로 설정',
  `terms_url` varchar(1000) COLLATE utf8mb4_0900_bin DEFAULT NULL COMMENT '원본 상품 약관 위치',
  `created_at` timestamp(6) NOT NULL COMMENT 'UTC 생성 시각',
  `updated_at` timestamp(6) NOT NULL COMMENT 'UTC 수정 시각',
  `image_key` varchar(1024) COLLATE utf8mb4_0900_bin DEFAULT NULL COMMENT '카드 앞면 이미지 S3 객체 키; 미수집은 NULL',
  PRIMARY KEY (`card_product_id`),
  UNIQUE KEY `uk_product_catalog` (`issuer_code`,`product_name`,`card_type`),
  CONSTRAINT `ck_product_cutoff` CHECK (((`billing_cutoff_days` is null) or (`billing_cutoff_days` > 0))),
  CONSTRAINT `ck_product_type` CHECK ((`card_type` in (_utf8mb4'CREDIT',_utf8mb4'CHECK')))
) ENGINE=InnoDB AUTO_INCREMENT=20 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin COMMENT='카드 상품';
/*!40101 SET character_set_client = @saved_cs_client */;

