--
-- Table structure for table `cashflow_item`
--

DROP TABLE IF EXISTS `cashflow_item`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `cashflow_item` (
  `cashflow_item_id` bigint NOT NULL AUTO_INCREMENT COMMENT '예정 내역 번호',
  `user_id` bigint NOT NULL COMMENT '내역 소유 사용자',
  `linked_account_id` bigint DEFAULT NULL COMMENT '예정 계좌; 미지정 가능',
  `title` varchar(150) COLLATE utf8mb4_0900_bin NOT NULL COMMENT '예정 내역 이름',
  `direction` varchar(16) COLLATE utf8mb4_0900_bin NOT NULL COMMENT 'INCOME / EXPENSE',
  `amount` bigint DEFAULT NULL COMMENT '발생 건 생성 시 기본 예정 금액; NULL 금액 미정, 0원과 구분',
  `scheduled_date` date NOT NULL COMMENT '한국 기준 첫 발생일; created_at과 별개',
  `recurrence_type` varchar(16) COLLATE utf8mb4_0900_bin NOT NULL COMMENT 'NONE / DAILY / WEEKLY / MONTHLY / YEARLY',
  `recurrence_end_date` date DEFAULT NULL COMMENT '한국 기준 반복 종료일',
  `recurrence_day_of_month` smallint DEFAULT NULL COMMENT '매월 반복 기준일(1~31), 그달에 없으면 말일; MONTHLY만, NULL이면 첫 발생일의 날짜',
  `status` varchar(24) COLLATE utf8mb4_0900_bin NOT NULL COMMENT '예정 내역 상태 코드',
  `memo` varchar(500) COLLATE utf8mb4_0900_bin DEFAULT NULL COMMENT '사용자 메모; 민감정보 입력 주의',
  `created_at` timestamp(6) NOT NULL COMMENT 'UTC 생성 시각',
  `updated_at` timestamp(6) NOT NULL COMMENT 'UTC 수정 시각',
  `version` bigint NOT NULL DEFAULT '0' COMMENT 'JPA 낙관적 락 버전',
  `user_card_id` bigint DEFAULT NULL COMMENT '예정 결제 카드; 같은 사용자 소유',
  `merchant_category_code` varchar(64) COLLATE utf8mb4_0900_bin DEFAULT NULL COMMENT '사용자가 지정한 업종 코드; 분류 정책은 POL-004',
  `item_kind` varchar(16) COLLATE utf8mb4_0900_bin NOT NULL DEFAULT 'SCHEDULED' COMMENT 'SCHEDULED / PURCHASE_PLAN; 기존 행은 일반 예정 항목',
  `payment_plan` varchar(16) COLLATE utf8mb4_0900_bin DEFAULT NULL COMMENT 'LUMP_SUM / INSTALLMENT; 카드 결제 방식',
  `installment_months` smallint DEFAULT NULL COMMENT '일시불 1, 할부 총 개월 수; 비카드 항목 NULL',
  `purchase_state` varchar(16) COLLATE utf8mb4_0900_bin DEFAULT NULL COMMENT '구매 계획만 ACTIVE / FULFILLED / CANCELED',
  `previous_cashflow_item_id` bigint DEFAULT NULL COMMENT '이후 일정 변경 시 이전 규칙; 기존 규칙과 이력은 보존',
  `product_category_code` varchar(64) COLLATE utf8mb4_0900_bin DEFAULT NULL COMMENT '구매할 물품 카테고리 코드; API productCategoryCode, 미지정 NULL',
  `product_name` varchar(150) COLLATE utf8mb4_0900_bin DEFAULT NULL COMMENT '구매할 상품명; API productName, 일정 표시 이름 title과 별도',
  `source` varchar(16) COLLATE utf8mb4_0900_bin NOT NULL DEFAULT 'MANUAL' COMMENT 'MANUAL 사용자 입력 / DETECTED 결제 이력 탐지',
  `detected_user_card_id` bigint DEFAULT NULL COMMENT '탐지 키: 반복 결제의 카드; 탐지 시리즈 첫 규칙만',
  `detected_merchant_id` bigint DEFAULT NULL COMMENT '탐지 키: 반복 결제의 가맹점; 탐지 시리즈 첫 규칙만',
  `detected_amount` bigint DEFAULT NULL COMMENT '탐지 키: 반복 결제의 승인 금액; 탐지 시리즈 첫 규칙만',
  PRIMARY KEY (`cashflow_item_id`),
  UNIQUE KEY `uk_cashflow_owner` (`cashflow_item_id`,`user_id`),
  UNIQUE KEY `uk_cashflow_item_detection` (`user_id`,`detected_user_card_id`,`detected_merchant_id`,`detected_amount`),
  KEY `ix_cashflow_owner_date` (`user_id`,`scheduled_date`),
  KEY `ix_cashflow_account_owner` (`linked_account_id`,`user_id`),
  KEY `ix_cashflow_card_owner` (`user_card_id`,`user_id`),
  KEY `ix_cashflow_previous_owner` (`previous_cashflow_item_id`,`user_id`),
  KEY `ix_cashflow_detected_card_owner` (`detected_user_card_id`,`user_id`),
  CONSTRAINT `fk_cashflow_account_owner` FOREIGN KEY (`linked_account_id`, `user_id`) REFERENCES `linked_account` (`linked_account_id`, `user_id`),
  CONSTRAINT `fk_cashflow_card_owner` FOREIGN KEY (`user_card_id`, `user_id`) REFERENCES `user_card` (`user_card_id`, `user_id`),
  CONSTRAINT `fk_cashflow_detected_card_owner` FOREIGN KEY (`detected_user_card_id`, `user_id`) REFERENCES `user_card` (`user_card_id`, `user_id`),
  CONSTRAINT `fk_cashflow_previous_owner` FOREIGN KEY (`previous_cashflow_item_id`, `user_id`) REFERENCES `cashflow_item` (`cashflow_item_id`, `user_id`),
  CONSTRAINT `fk_cashflow_user` FOREIGN KEY (`user_id`) REFERENCES `app_user` (`user_id`),
  CONSTRAINT `ck_cashflow_amount` CHECK (((`amount` is null) or (`amount` > 0))),
  CONSTRAINT `ck_cashflow_card_direction` CHECK (((`user_card_id` is null) or (`direction` = _utf8mb4'EXPENSE'))),
  CONSTRAINT `ck_cashflow_detection_key` CHECK ((((`detected_user_card_id` is null) and (`detected_merchant_id` is null) and (`detected_amount` is null)) or ((`source` = _utf8mb4'DETECTED') and (`detected_user_card_id` is not null) and (`detected_merchant_id` is not null) and (`detected_amount` > 0)))),
  CONSTRAINT `ck_cashflow_direction` CHECK ((`direction` in (_utf8mb4'INCOME',_utf8mb4'EXPENSE'))),
  CONSTRAINT `ck_cashflow_end` CHECK (((`recurrence_end_date` is null) or (`recurrence_end_date` >= `scheduled_date`))),
  CONSTRAINT `ck_cashflow_item_version` CHECK ((`version` >= 0)),
  CONSTRAINT `ck_cashflow_kind` CHECK ((`item_kind` in (_utf8mb4'SCHEDULED',_utf8mb4'PURCHASE_PLAN'))),
  CONSTRAINT `ck_cashflow_plan` CHECK ((((`payment_plan` is null) and (`installment_months` is null)) or ((`user_card_id` is not null) and (`payment_plan` is not null) and (`installment_months` is not null) and (((`payment_plan` = _utf8mb4'LUMP_SUM') and (`installment_months` = 1)) or ((`payment_plan` = _utf8mb4'INSTALLMENT') and (`installment_months` >= 2)))))),
  CONSTRAINT `ck_cashflow_purchase` CHECK ((((`item_kind` = _utf8mb4'SCHEDULED') and (`purchase_state` is null)) or ((`item_kind` = _utf8mb4'PURCHASE_PLAN') and (`direction` = _utf8mb4'EXPENSE') and (`user_card_id` is not null) and (`amount` is not null) and (`payment_plan` is not null) and (`purchase_state` is not null) and (`purchase_state` in (_utf8mb4'ACTIVE',_utf8mb4'FULFILLED',_utf8mb4'CANCELED'))))),
  CONSTRAINT `ck_cashflow_recurrence` CHECK ((`recurrence_type` in (_utf8mb4'NONE',_utf8mb4'DAILY',_utf8mb4'WEEKLY',_utf8mb4'MONTHLY',_utf8mb4'YEARLY'))),
  CONSTRAINT `ck_cashflow_recurrence_day` CHECK (((`recurrence_day_of_month` is null) or ((`recurrence_type` = _utf8mb4'MONTHLY') and (`recurrence_day_of_month` between 1 and 31) and (dayofmonth(`scheduled_date`) = least(`recurrence_day_of_month`,dayofmonth(last_day(`scheduled_date`))))))),
  CONSTRAINT `ck_cashflow_source` CHECK ((`source` in (_utf8mb4'MANUAL',_utf8mb4'DETECTED')))
) ENGINE=InnoDB AUTO_INCREMENT=100 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin COMMENT='직접 입력한 예정 수입·지출';
/*!40101 SET character_set_client = @saved_cs_client */;

