--
-- Table structure for table `cashflow_occurrence`
--

DROP TABLE IF EXISTS `cashflow_occurrence`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `cashflow_occurrence` (
  `cashflow_occurrence_id` bigint NOT NULL AUTO_INCREMENT COMMENT '예정 발생 건 번호; 실제 출금 기록 아님',
  `cashflow_item_id` bigint NOT NULL COMMENT '반복 규칙 또는 일회성 항목',
  `user_id` bigint NOT NULL COMMENT '규칙과 동일 사용자',
  `occurrence_date` date NOT NULL COMMENT '한국 기준 원래 발생일; 이번 건 날짜를 바꿔도 식별용으로 보존',
  `scheduled_date` date NOT NULL COMMENT '한국 기준 이번 건에 적용할 예정일',
  `title` varchar(150) COLLATE utf8mb4_0900_bin NOT NULL COMMENT '이번 건 이름',
  `direction` varchar(16) COLLATE utf8mb4_0900_bin NOT NULL COMMENT 'INCOME / EXPENSE',
  `amount` bigint DEFAULT NULL COMMENT '이번 건 예정 원화 금액; NULL이면 금액 입력 안내 후 예보 계산 제외',
  `linked_account_id` bigint DEFAULT NULL COMMENT '이번 건 계좌 직접 입출금 계좌; 같은 사용자 소유',
  `user_card_id` bigint DEFAULT NULL COMMENT '이번 건 예정 결제 카드; 같은 사용자 소유',
  `merchant_category_code` varchar(64) COLLATE utf8mb4_0900_bin DEFAULT NULL COMMENT '이번 건 업종 코드',
  `payment_plan` varchar(16) COLLATE utf8mb4_0900_bin DEFAULT NULL COMMENT 'LUMP_SUM / INSTALLMENT; 비카드 항목 NULL',
  `installment_months` smallint DEFAULT NULL COMMENT '일시불 1, 할부 총 개월 수',
  `status` varchar(24) COLLATE utf8mb4_0900_bin NOT NULL COMMENT 'CONFIRMED 예정 / EXCLUDED 이번 건 제외; 기존 상태는 변환 없이 보존',
  `is_overridden` tinyint(1) NOT NULL DEFAULT '0' COMMENT '이번 건만 수정했는지 여부; 이후 일괄 변경 시 판정 근거',
  `memo` varchar(500) COLLATE utf8mb4_0900_bin DEFAULT NULL COMMENT '이번 건 메모; 민감정보 입력 주의',
  `created_at` timestamp(6) NOT NULL COMMENT 'UTC 생성 시각',
  `updated_at` timestamp(6) NOT NULL COMMENT 'UTC 수정 시각',
  `version` bigint NOT NULL DEFAULT '0' COMMENT 'JPA 낙관적 락 버전',
  `product_category_code` varchar(64) COLLATE utf8mb4_0900_bin DEFAULT NULL COMMENT '이번 건 물품 카테고리 코드; API productCategoryCode, 미지정 NULL',
  `product_name` varchar(150) COLLATE utf8mb4_0900_bin DEFAULT NULL COMMENT '이번 건 구매할 상품명; API productName, 일정 표시 이름 title과 별도',
  PRIMARY KEY (`cashflow_occurrence_id`),
  UNIQUE KEY `uk_occurrence_slot` (`cashflow_item_id`,`occurrence_date`),
  UNIQUE KEY `uk_occurrence_owner` (`cashflow_occurrence_id`,`user_id`),
  KEY `ix_occurrence_owner_date` (`user_id`,`scheduled_date`),
  KEY `ix_occurrence_rule_owner` (`cashflow_item_id`,`user_id`),
  KEY `ix_occurrence_account_owner` (`linked_account_id`,`user_id`),
  KEY `ix_occurrence_card_owner` (`user_card_id`,`user_id`),
  CONSTRAINT `fk_occurrence_account_owner` FOREIGN KEY (`linked_account_id`, `user_id`) REFERENCES `linked_account` (`linked_account_id`, `user_id`),
  CONSTRAINT `fk_occurrence_card_owner` FOREIGN KEY (`user_card_id`, `user_id`) REFERENCES `user_card` (`user_card_id`, `user_id`),
  CONSTRAINT `fk_occurrence_rule_owner` FOREIGN KEY (`cashflow_item_id`, `user_id`) REFERENCES `cashflow_item` (`cashflow_item_id`, `user_id`),
  CONSTRAINT `ck_occurrence_amount` CHECK (((`amount` is null) or (`amount` > 0))),
  CONSTRAINT `ck_occurrence_card_direction` CHECK (((`user_card_id` is null) or (`direction` = _utf8mb4'EXPENSE'))),
  CONSTRAINT `ck_occurrence_direction` CHECK ((`direction` in (_utf8mb4'INCOME',_utf8mb4'EXPENSE'))),
  CONSTRAINT `ck_occurrence_override` CHECK ((`is_overridden` in (0,1))),
  CONSTRAINT `ck_occurrence_plan` CHECK ((((`payment_plan` is null) and (`installment_months` is null)) or ((`user_card_id` is not null) and (`payment_plan` is not null) and (`installment_months` is not null) and (((`payment_plan` = _utf8mb4'LUMP_SUM') and (`installment_months` = 1)) or ((`payment_plan` = _utf8mb4'INSTALLMENT') and (`installment_months` >= 2)))))),
  CONSTRAINT `ck_occurrence_version` CHECK ((`version` >= 0))
) ENGINE=InnoDB AUTO_INCREMENT=123 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin COMMENT='회차별 예정 수입·지출';
/*!40101 SET character_set_client = @saved_cs_client */;

