--
-- Table structure for table `limit_group`
--

DROP TABLE IF EXISTS `limit_group`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `limit_group` (
  `limit_group_id` bigint NOT NULL AUTO_INCREMENT COMMENT '한도 그룹 버전 번호',
  `card_product_id` bigint NOT NULL COMMENT '대상 상품',
  `group_code` varchar(64) COLLATE utf8mb4_0900_bin NOT NULL COMMENT '상품 내 한도 규칙 식별 코드; 영문 대문자·밑줄(예: LIFE_SHARED), 버전 간 유지, 금액·버전 번호 제외',
  `policy_version` smallint NOT NULL COMMENT '한도 정책 버전 1~32767',
  `group_name` varchar(150) COLLATE utf8mb4_0900_bin NOT NULL COMMENT '공유 한도 이름',
  `period_type` varchar(16) COLLATE utf8mb4_0900_bin NOT NULL COMMENT 'PER_TRANSACTION / DAILY / MONTHLY',
  `limit_unit` varchar(16) COLLATE utf8mb4_0900_bin NOT NULL COMMENT 'KRW: 원 / POINT: 포인트 / COUNT: 횟수; 한도값·사용량의 단위',
  `base_limit_value` bigint DEFAULT NULL COMMENT '기본 한도; 실적 구간별 값만 있으면 NULL',
  `valid_from` date DEFAULT NULL COMMENT '한도 규칙의 공식 적용 시작일; 한국 날짜, 포함, 미확인 NULL',
  `valid_until` date DEFAULT NULL COMMENT '한도 규칙의 공식 적용 종료일; 한국 날짜, 미포함, 종료일 미확인·미정 NULL',
  `created_at` timestamp(6) NOT NULL COMMENT 'UTC 생성 시각',
  PRIMARY KEY (`limit_group_id`),
  UNIQUE KEY `uk_limit_version` (`card_product_id`,`group_code`,`policy_version`),
  UNIQUE KEY `uk_limit_product` (`limit_group_id`,`card_product_id`),
  CONSTRAINT `fk_limit_product` FOREIGN KEY (`card_product_id`) REFERENCES `card_product` (`card_product_id`),
  CONSTRAINT `ck_limit_dates` CHECK (((`valid_from` is null) or (`valid_until` is null) or (`valid_until` > `valid_from`))),
  CONSTRAINT `ck_limit_period` CHECK ((`period_type` in (_utf8mb4'PER_TRANSACTION',_utf8mb4'DAILY',_utf8mb4'MONTHLY'))),
  CONSTRAINT `ck_limit_unit` CHECK ((`limit_unit` in (_utf8mb4'KRW',_utf8mb4'POINT',_utf8mb4'COUNT'))),
  CONSTRAINT `ck_limit_value` CHECK (((`base_limit_value` is null) or (`base_limit_value` >= 0))),
  CONSTRAINT `ck_limit_version` CHECK ((`policy_version` > 0))
) ENGINE=InnoDB AUTO_INCREMENT=126 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin COMMENT='한도 정책 버전';
/*!40101 SET character_set_client = @saved_cs_client */;

