--
-- Table structure for table `linked_account`
--

DROP TABLE IF EXISTS `linked_account`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `linked_account` (
  `linked_account_id` bigint NOT NULL AUTO_INCREMENT COMMENT 'YAMU 연결 계좌 번호',
  `user_id` bigint NOT NULL COMMENT '계좌 소유 사용자',
  `bank_code` varchar(20) CHARACTER SET ascii COLLATE ascii_general_ci NOT NULL COMMENT '금융망 은행 코드; 문자열',
  `account_no_enc` varbinary(2048) NOT NULL COMMENT '금융망 계좌번호 암호화 봉투',
  `account_no_hash` binary(32) NOT NULL COMMENT '은행코드·정규화 계좌번호의 조회용 keyed HMAC',
  `account_name` varchar(100) COLLATE utf8mb4_0900_bin DEFAULT NULL COMMENT '계좌 표시명',
  `account_alias` varchar(100) COLLATE utf8mb4_0900_bin DEFAULT NULL COMMENT '사용자가 지정한 계좌 별칭; 미지정 NULL',
  `account_last4` char(4) CHARACTER SET ascii COLLATE ascii_general_ci DEFAULT NULL COMMENT '마스킹 표시용 마지막 네 자리',
  `status` varchar(20) COLLATE utf8mb4_0900_bin NOT NULL DEFAULT 'CONNECTED' COMMENT 'CONNECTED / DISCONNECTED',
  `is_primary` tinyint(1) NOT NULL DEFAULT '0' COMMENT '기준 계좌 여부(홈 기본 계좌 미리보기); 사용자당 최대 1개, 연결된 계좌만',
  `primary_owner_id` bigint GENERATED ALWAYS AS ((case when (`is_primary` = 1) then `user_id` end)) STORED COMMENT '기준 계좌면 user_id, 아니면 NULL; 사용자당 기준 계좌 1개 UNIQUE용 생성 칼럼',
  `step_up_audit_log_id` bigint DEFAULT NULL COMMENT '연결 시 사용한 PIN·생체 추가 인증 근거; 1원 인증과 구분',
  `connected_at` timestamp(6) NOT NULL COMMENT 'UTC 최근 연결 시각',
  `disconnected_at` timestamp(6) NULL DEFAULT NULL COMMENT 'UTC 최근 연결 해제 시각',
  `created_at` timestamp(6) NOT NULL COMMENT 'UTC 생성 시각',
  `updated_at` timestamp(6) NOT NULL COMMENT 'UTC 수정 시각',
  `version` bigint NOT NULL DEFAULT '0' COMMENT 'JPA 낙관적 락 버전',
  PRIMARY KEY (`linked_account_id`),
  UNIQUE KEY `uk_account_identity` (`user_id`,`bank_code`,`account_no_hash`),
  UNIQUE KEY `uk_account_owner` (`linked_account_id`,`user_id`),
  UNIQUE KEY `uk_account_primary_owner` (`primary_owner_id`),
  KEY `ix_account_audit_owner` (`step_up_audit_log_id`,`user_id`),
  CONSTRAINT `fk_account_audit_owner` FOREIGN KEY (`step_up_audit_log_id`, `user_id`) REFERENCES `step_up_audit_log` (`step_up_audit_log_id`, `user_id`),
  CONSTRAINT `fk_account_user` FOREIGN KEY (`user_id`) REFERENCES `app_user` (`user_id`),
  CONSTRAINT `ck_account_primary_connected` CHECK (((`is_primary` = 0) or (`status` = _utf8mb4'CONNECTED'))),
  CONSTRAINT `ck_account_primary_flag` CHECK ((`is_primary` in (0,1))),
  CONSTRAINT `ck_account_status` CHECK ((`status` in (_utf8mb4'CONNECTED',_utf8mb4'DISCONNECTED'))),
  CONSTRAINT `ck_linked_account_version` CHECK ((`version` >= 0))
) ENGINE=InnoDB AUTO_INCREMENT=28 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin COMMENT='연결 계좌 참조';
/*!40101 SET character_set_client = @saved_cs_client */;

