DROP TABLE IF EXISTS `merchant`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `merchant` (
  `merchant_id` bigint NOT NULL AUTO_INCREMENT COMMENT 'YAMU 서버 발급 브랜드 단위 가맹점 번호',
  `merchant_name` varchar(150) COLLATE utf8mb4_0900_bin NOT NULL COMMENT '브랜드명; 예: 스타벅스',
  `brand_code` varchar(64) COLLATE utf8mb4_0900_bin NOT NULL COMMENT 'YAMU 내부 고유 브랜드 코드',
  `merchant_category_code` varchar(64) COLLATE utf8mb4_0900_bin NOT NULL COMMENT '업종 식별 코드',
  `created_at` timestamp(6) NOT NULL COMMENT 'UTC 생성 시각',
  `updated_at` timestamp(6) NOT NULL COMMENT 'UTC 수정 시각',
  PRIMARY KEY (`merchant_id`),
  UNIQUE KEY `uk_merchant_brand` (`brand_code`),
  KEY `ix_merchant_category` (`merchant_category_code`)
) ENGINE=InnoDB AUTO_INCREMENT=104 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin COMMENT='브랜드 단위 가맹점';
