--
-- Table structure for table `monthly_limit_usage`
--

DROP TABLE IF EXISTS `monthly_limit_usage`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `monthly_limit_usage` (
  `monthly_limit_usage_id` bigint NOT NULL AUTO_INCREMENT COMMENT '월간 한도 사용 번호',
  `user_card_id` bigint NOT NULL COMMENT '보유 카드',
  `card_product_id` bigint NOT NULL COMMENT '카드·한도 상품 일치 검증용',
  `limit_group_id` bigint NOT NULL COMMENT '한도 그룹 버전',
  `usage_month` date NOT NULL COMMENT '한국 기준 월의 1일',
  `used_value` bigint NOT NULL COMMENT '확정된 한도 사용량; 금액 또는 횟수, 신규 카드·확인된 미사용은 0',
  `created_at` timestamp(6) NOT NULL COMMENT 'UTC 생성 시각',
  `updated_at` timestamp(6) NOT NULL COMMENT 'UTC 수정 시각',
  `version` bigint NOT NULL DEFAULT '0' COMMENT 'JPA 낙관적 락 버전',
  PRIMARY KEY (`monthly_limit_usage_id`),
  UNIQUE KEY `uk_usage_card_limit_month` (`user_card_id`,`limit_group_id`,`usage_month`),
  KEY `ix_usage_card_product` (`user_card_id`,`card_product_id`),
  KEY `ix_usage_limit_product` (`limit_group_id`,`card_product_id`),
  CONSTRAINT `fk_usage_card_product` FOREIGN KEY (`user_card_id`, `card_product_id`) REFERENCES `user_card` (`user_card_id`, `card_product_id`),
  CONSTRAINT `fk_usage_limit_product` FOREIGN KEY (`limit_group_id`, `card_product_id`) REFERENCES `limit_group` (`limit_group_id`, `card_product_id`),
  CONSTRAINT `ck_monthly_limit_usage_version` CHECK ((`version` >= 0)),
  CONSTRAINT `ck_usage_month` CHECK ((dayofmonth(`usage_month`) = 1)),
  CONSTRAINT `ck_usage_value` CHECK ((`used_value` >= 0))
) ENGINE=InnoDB AUTO_INCREMENT=1450 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin COMMENT='카드별 월간 한도 사용량';
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `monthly_limit_usage`
--

LOCK TABLES `monthly_limit_usage` WRITE;
/*!40000 ALTER TABLE `monthly_limit_usage` DISABLE KEYS */;
