  `body` varchar(1000) COLLATE utf8mb4_0900_bin NOT NULL COMMENT '알림 내용',
  `target_type` varchar(32) COLLATE utf8mb4_0900_bin DEFAULT NULL COMMENT '앱 이동 대상 유형; 권한은 서비스에서 확인',
  `target_id` bigint DEFAULT NULL COMMENT '앱 이동 대상 번호; 다형 참조이므로 FK 없음',
  `read_at` timestamp(6) NULL DEFAULT NULL COMMENT 'UTC 읽은 시각',
  `created_at` timestamp(6) NOT NULL COMMENT 'UTC 생성 시각',
  `updated_at` timestamp(6) NOT NULL COMMENT 'UTC 수정 시각',
  PRIMARY KEY (`notification_id`),
  UNIQUE KEY `uk_notification_dedup` (`user_id`,`deduplication_key`),
  KEY `ix_notification_owner_time` (`user_id`,`created_at`),
  CONSTRAINT `fk_notification_user` FOREIGN KEY (`user_id`) REFERENCES `app_user` (`user_id`),
  CONSTRAINT `ck_notification_target` CHECK ((((`target_type` is null) and (`target_id` is null)) or ((`target_type` is not null) and (`target_id` is not null))))
) ENGINE=InnoDB AUTO_INCREMENT=807 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin COMMENT='사용자 알림';
