--
-- Table structure for table `payment_benefit`
--

DROP TABLE IF EXISTS `payment_benefit`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `payment_benefit` (
  `payment_benefit_id` bigint NOT NULL AUTO_INCREMENT COMMENT '혜택 적용 결과 번호',
  `payment_transaction_id` bigint NOT NULL COMMENT '결제 거래',
  `card_product_id` bigint NOT NULL COMMENT '거래·혜택 상품 일치 검증용',
  `card_benefit_id` bigint NOT NULL COMMENT '적용한 혜택 정책 버전',
  `benefit_value` decimal(19,6) NOT NULL COMMENT '실제로 적용한 할인·캐시백·적립 결과; 원화 또는 포인트, 한도 소모량과 구분',
  `value_unit` varchar(16) COLLATE utf8mb4_0900_bin NOT NULL COMMENT 'KRW / POINT',
  `krw_amount` bigint DEFAULT NULL COMMENT '확인 가능한 원화 혜택 금액; 미환산 NULL',
  `created_at` timestamp(6) NOT NULL COMMENT 'UTC 생성 시각',
  `confirmed_at` datetime(6) DEFAULT NULL,
  `confirmation_source` varchar(32) COLLATE utf8mb4_0900_bin DEFAULT NULL,
  PRIMARY KEY (`payment_benefit_id`),
  UNIQUE KEY `uk_payment_benefit` (`payment_transaction_id`,`card_benefit_id`),
  KEY `ix_applied_payment_product` (`payment_transaction_id`,`card_product_id`),
  KEY `ix_applied_benefit_product` (`card_benefit_id`,`card_product_id`),
  CONSTRAINT `fk_applied_benefit_product` FOREIGN KEY (`card_benefit_id`, `card_product_id`) REFERENCES `card_benefit` (`card_benefit_id`, `card_product_id`),
  CONSTRAINT `fk_applied_payment_product` FOREIGN KEY (`payment_transaction_id`, `card_product_id`) REFERENCES `payment_transaction` (`payment_transaction_id`, `card_product_id`),
  CONSTRAINT `ck_applied_unit` CHECK ((`value_unit` in (_utf8mb4'KRW',_utf8mb4'POINT'))),
  CONSTRAINT `ck_applied_values` CHECK (((`benefit_value` >= 0) and ((`krw_amount` is null) or (`krw_amount` >= 0)))),
  CONSTRAINT `ck_benefit_confirmation_pair` CHECK ((((`confirmed_at` is null) and (`confirmation_source` is null)) or ((`confirmed_at` is not null) and (`confirmation_source` is not null) and (`confirmation_source` = _utf8mb4'QA_HISTORY'))))
) ENGINE=InnoDB AUTO_INCREMENT=174 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin COMMENT='결제별 실제 적용 혜택 결과';
/*!40101 SET character_set_client = @saved_cs_client */;

