--
-- Table structure for table `payment_limit_usage`
--

DROP TABLE IF EXISTS `payment_limit_usage`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `payment_limit_usage` (
  `payment_limit_usage_id` bigint NOT NULL AUTO_INCREMENT COMMENT '한도 사용 근거 번호',
  `payment_transaction_id` bigint NOT NULL COMMENT '결제 거래',
  `card_product_id` bigint NOT NULL COMMENT '거래·한도 상품 일치 검증용',
  `limit_group_id` bigint NOT NULL COMMENT '결제 당시 한도 그룹 버전',
  `remaining_before` bigint NOT NULL COMMENT '이 거래가 한도를 소모하기 직전 남은 금액·횟수; 단위는 한도 그룹',
  `consumed_value` bigint NOT NULL COMMENT '이 거래로 차감한 한도 금액·횟수; 실제 혜택 결과는 PAYMENT_BENEFIT, 취소 시 이 소모량만 복구',
  `usage_date` date NOT NULL COMMENT '한국 기준 사용일; 일별 검사',
  `usage_month` date NOT NULL COMMENT '한국 기준 사용 월의 1일',
  `restored_at` timestamp(6) NULL DEFAULT NULL COMMENT 'UTC 취소 복구 완료 시각',
  `created_at` timestamp(6) NOT NULL COMMENT 'UTC 생성 시각',
  `updated_at` timestamp(6) NOT NULL COMMENT 'UTC 수정 시각',
  `version` bigint NOT NULL DEFAULT '0' COMMENT 'JPA 낙관적 락 버전',
  PRIMARY KEY (`payment_limit_usage_id`),
  UNIQUE KEY `uk_payment_limit` (`payment_transaction_id`,`limit_group_id`),
  KEY `ix_impact_daily` (`limit_group_id`,`usage_date`,`payment_transaction_id`),
  KEY `ix_impact_payment_product` (`payment_transaction_id`,`card_product_id`),
  KEY `ix_impact_limit_product` (`limit_group_id`,`card_product_id`),
  CONSTRAINT `fk_impact_limit_product` FOREIGN KEY (`limit_group_id`, `card_product_id`) REFERENCES `limit_group` (`limit_group_id`, `card_product_id`),
  CONSTRAINT `fk_impact_payment_product` FOREIGN KEY (`payment_transaction_id`, `card_product_id`) REFERENCES `payment_transaction` (`payment_transaction_id`, `card_product_id`),
  CONSTRAINT `ck_impact_month` CHECK (((dayofmonth(`usage_month`) = 1) and (year(`usage_month`) = year(`usage_date`)) and (month(`usage_month`) = month(`usage_date`)))),
  CONSTRAINT `ck_impact_value` CHECK (((`remaining_before` >= 0) and (`consumed_value` >= 0) and (`consumed_value` <= `remaining_before`))),
  CONSTRAINT `ck_payment_limit_usage_version` CHECK ((`version` >= 0))
) ENGINE=InnoDB AUTO_INCREMENT=536 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin COMMENT='결제별 한도 사용 내역과 취소 복구 기록';
/*!40101 SET character_set_client = @saved_cs_client */;

