--
-- Table structure for table `payment_transaction`
--

DROP TABLE IF EXISTS `payment_transaction`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `payment_transaction` (
  `payment_transaction_id` bigint NOT NULL AUTO_INCREMENT COMMENT '결제 거래 번호',
  `user_id` bigint NOT NULL COMMENT '결제 요청 사용자',
  `user_card_id` bigint DEFAULT NULL COMMENT '승인 카드; 선택 전 요청에는 NULL',
  `card_product_id` bigint DEFAULT NULL COMMENT '선택 카드의 상품; 교차 상품 적용 방지',
  `recommended_rank` smallint DEFAULT NULL COMMENT '승인한(마지막 시도) 카드의 추천 순위, 1부터. 추천 밖 카드·기록 전 결제·SEED는 NULL',
  `user_selected` tinyint(1) DEFAULT NULL COMMENT '마지막 시도의 카드를 사용자가 직접 골랐는지. 기록 전 결제·SEED는 NULL',
  `merchant_id` bigint NOT NULL COMMENT '결제한 브랜드 단위 가맹점',
  `payment_channel` varchar(16) COLLATE utf8mb4_0900_bin NOT NULL DEFAULT 'UNKNOWN' COMMENT 'ONLINE / OFFLINE / UNKNOWN; 서버가 확인한 거래 채널',
  `facility_type` varchar(32) COLLATE utf8mb4_0900_bin DEFAULT NULL COMMENT '입점 시설: GENERAL / DEPARTMENT_STORE / DISCOUNT_STORE / DUTY_FREE / OUTLET / SHOPPING_MALL / AIRPORT / HOTEL / RESORT / TRAIN_STATION; 미확인 NULL; FR-014 기준, 서버 허용값 검증',
  `merchant_context_snapshot` json DEFAULT NULL COMMENT '서버 확인 POS·브랜드 코드·업종·거래 조건의 당시 근거; 사용자 입력으로 확정 금지',
  `request_key` char(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'POS 생성 UUID; 재시도 때 같은 값',
  `request_fingerprint` binary(32) NOT NULL COMMENT '최초 요청 불변 내용의 SHA-256; 중복 키 요청 비교',
  `source` varchar(16) COLLATE utf8mb4_0900_bin NOT NULL COMMENT 'YAMU / SEED',
  `status` varchar(24) COLLATE utf8mb4_0900_bin NOT NULL COMMENT '결제 처리 상태 코드; REQUESTED 등 API 계약',
  `requested_amount` bigint NOT NULL COMMENT '최초 요청 금액; 양수',
  `approved_amount` bigint DEFAULT NULL COMMENT '확정 모의 승인 금액; 전액 할인 시 0 가능',
  `installment_months` smallint DEFAULT NULL COMMENT '일시불은 1, 할부는 총 개월 수(3개월 할부는 3); 현재 회차 번호가 아님. 지원 개월은 서비스 검증',
  `recognized_performance_amount` bigint DEFAULT NULL COMMENT '승인 당시 실적 인정액; 미확정은 NULL',
  `performance_basis_amount` bigint DEFAULT NULL COMMENT '혜택 계산에 사용한 전월 실적 인정액(원); 실제 0원은 0, 미확정·미사용은 NULL',
  `performance_month` date DEFAULT NULL COMMENT '이 결제의 실적을 합산할 월(한국 기준); 2026년 10월은 2026-10-01, 1일은 월 표시용이며 실제 결제일이 아님; 미확정 NULL',
  `requested_at` timestamp(6) NOT NULL COMMENT 'UTC 요청 시각',
  `approved_at` timestamp(6) NULL DEFAULT NULL COMMENT 'UTC 승인 시각',
  `canceled_at` timestamp(6) NULL DEFAULT NULL COMMENT 'UTC 전체 취소 시각',
  `performance_reversed_at` timestamp(6) NULL DEFAULT NULL COMMENT 'UTC 실적 복구 완료 시각; 서비스에서 1회 처리',
  `failure_code` varchar(64) COLLATE utf8mb4_0900_bin DEFAULT NULL COMMENT '승인 거절 시 API failure.code와 동일: INSUFFICIENT_BALANCE / CREDIT_LIMIT_EXCEEDED / CARD_SUSPENDED / UNPAID_BILL / ISSUER_DECLINED; 거절 사유 없으면 NULL; 서버 허용값 검증',
  `fin_request_no` char(20) CHARACTER SET ascii COLLATE ascii_bin DEFAULT NULL COMMENT 'SSAFY institutionTransactionUniqueNo; YYYYMMDD+HHMMSS+일련번호 6자리; 서버 공통 Redis INCR 채번, 금융망 새 호출마다 새 번호',
  `fin_request_amount` bigint DEFAULT NULL COMMENT '이번 시도의 금융망 출금 요청액(결제 금액 - 즉시할인); fin_request_no와 함께 저장·삭제, 출금 요청 전 NULL',
  `fin_transaction_no` varchar(128) CHARACTER SET ascii COLLATE ascii_bin DEFAULT NULL COMMENT '확인한 금융망 거래 참조',
  `refund_linked_account_id` bigint DEFAULT NULL COMMENT '체크카드 취소 환불을 입금한 계좌. 0원 승인·신용카드·취소 전은 NULL',
  `created_at` timestamp(6) NOT NULL COMMENT 'UTC 생성 시각',
  `updated_at` timestamp(6) NOT NULL COMMENT 'UTC 수정 시각',
  `version` bigint NOT NULL DEFAULT '0' COMMENT 'JPA 낙관적 락 버전',
  `spending_class` varchar(16) COLLATE utf8mb4_0900_bin DEFAULT NULL COMMENT 'LIVING / LARGE / EXCLUDED; 미분류 NULL, 실적 인정액과 별개',
  `spending_class_source` varchar(16) COLLATE utf8mb4_0900_bin DEFAULT NULL COMMENT 'AUTO / USER; 미분류 NULL, USER 수정은 재분류로 덮어쓰지 않음',
  `memo` varchar(100) COLLATE utf8mb4_0900_bin DEFAULT NULL COMMENT '사용자 결제 메모; 민감정보 입력 금지',
  `memo_updated_at` timestamp(6) NULL DEFAULT NULL COMMENT 'UTC 메모를 남기거나 지운 마지막 시각; 메모 API만 바꿈, 메모를 고친 적 없으면 NULL',
  `purchase_item_code` varchar(64) COLLATE utf8mb4_0900_bin DEFAULT NULL,
  `recommendation_result_json` json DEFAULT NULL,
  PRIMARY KEY (`payment_transaction_id`),
  UNIQUE KEY `uk_payment_request` (`request_key`),
  UNIQUE KEY `uk_payment_owner` (`payment_transaction_id`,`user_id`),
  UNIQUE KEY `uk_payment_product` (`payment_transaction_id`,`card_product_id`),
  UNIQUE KEY `uk_payment_card_owner` (`payment_transaction_id`,`user_id`,`user_card_id`),
  KEY `ix_payment_owner_time` (`user_id`,`requested_at`),
  KEY `ix_payment_card_time` (`user_card_id`,`approved_at`),
  KEY `ix_payment_card_owner_product` (`user_card_id`,`user_id`,`card_product_id`),
  KEY `fk_payment_merchant` (`merchant_id`),
  KEY `fk_payment_purchase_item` (`purchase_item_code`),
  KEY `ix_payment_refund_account_owner` (`refund_linked_account_id`,`user_id`),
  CONSTRAINT `fk_payment_card_owner_product` FOREIGN KEY (`user_card_id`, `user_id`, `card_product_id`) REFERENCES `user_card` (`user_card_id`, `user_id`, `card_product_id`),
  CONSTRAINT `fk_payment_merchant` FOREIGN KEY (`merchant_id`) REFERENCES `merchant` (`merchant_id`),
  CONSTRAINT `fk_payment_purchase_item` FOREIGN KEY (`purchase_item_code`) REFERENCES `purchase_item` (`purchase_item_code`) ON DELETE RESTRICT,
  CONSTRAINT `fk_payment_refund_account_owner` FOREIGN KEY (`refund_linked_account_id`, `user_id`) REFERENCES `linked_account` (`linked_account_id`, `user_id`),
  CONSTRAINT `fk_payment_user` FOREIGN KEY (`user_id`) REFERENCES `app_user` (`user_id`),
  CONSTRAINT `ck_payment_amounts` CHECK (((`requested_amount` > 0) and ((`approved_amount` is null) or (`approved_amount` >= 0)) and ((`recognized_performance_amount` is null) or (`recognized_performance_amount` >= 0)))),
  CONSTRAINT `ck_payment_approval` CHECK (((`approved_at` is null) or ((`user_card_id` is not null) and (`approved_amount` is not null) and (`performance_month` is not null) and (`installment_months` is not null)))),
  CONSTRAINT `ck_payment_cancellation` CHECK (((`canceled_at` is null) or (`approved_at` is not null))),
  CONSTRAINT `ck_payment_card_pair` CHECK ((((`user_card_id` is null) and (`card_product_id` is null)) or ((`user_card_id` is not null) and (`card_product_id` is not null)))),
  CONSTRAINT `ck_payment_channel` CHECK ((`payment_channel` in (_utf8mb4'ONLINE',_utf8mb4'OFFLINE',_utf8mb4'UNKNOWN'))),
  CONSTRAINT `ck_payment_fin_request_amount` CHECK (((`fin_request_amount` is null) or (`fin_request_amount` > 0))),
  CONSTRAINT `ck_payment_installment` CHECK (((`installment_months` is null) or (`installment_months` > 0))),
  CONSTRAINT `ck_payment_month` CHECK (((`performance_month` is null) or (dayofmonth(`performance_month`) = 1))),
  CONSTRAINT `ck_payment_performance_basis` CHECK (((`performance_basis_amount` is null) or (`performance_basis_amount` >= 0))),
  CONSTRAINT `ck_payment_recommended_rank` CHECK (((`recommended_rank` is null) or (`recommended_rank` >= 1))),
  CONSTRAINT `ck_payment_source` CHECK ((`source` in (_utf8mb4'YAMU',_utf8mb4'SEED'))),
  CONSTRAINT `ck_payment_spending_class` CHECK (((`spending_class` is null) or (`spending_class` in (_utf8mb4'LIVING',_utf8mb4'LARGE',_utf8mb4'EXCLUDED')))),
  CONSTRAINT `ck_payment_spending_pair` CHECK ((((`spending_class` is null) and (`spending_class_source` is null)) or ((`spending_class` is not null) and (`spending_class_source` is not null) and (`spending_class_source` in (_utf8mb4'AUTO',_utf8mb4'USER'))))),
  CONSTRAINT `ck_payment_transaction_version` CHECK ((`version` >= 0))
) ENGINE=InnoDB AUTO_INCREMENT=4348 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin COMMENT='결제 요청·승인·취소';
