--
-- Table structure for table `performance_decision`
--

DROP TABLE IF EXISTS `performance_decision`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `performance_decision` (
  `performance_decision_id` bigint NOT NULL AUTO_INCREMENT COMMENT '실적 판단 기록 번호',
  `user_id` bigint NOT NULL COMMENT '판단한 사용자',
  `user_card_id` bigint NOT NULL COMMENT '판단한 카드',
  `performance_month` date NOT NULL COMMENT '판단한 실적 월(한국 기준)의 1일',
  `decision` varchar(16) COLLATE utf8mb4_0900_bin DEFAULT NULL COMMENT 'FILL 채우기 · KEEP 평소대로 · SKIP 안 채우기; NULL은 되돌린 상태',
  `guide` varchar(40) COLLATE utf8mb4_0900_bin DEFAULT NULL COMMENT '기록할 때 서버 판정(PerformanceGuide); 판정할 수 없으면 NULL',
  `analysis_version` varchar(40) COLLATE utf8mb4_0900_bin DEFAULT NULL COMMENT '앱이 근거로 본 분석의 asOf; 보내지 않았으면 NULL',
  `notifications_muted` tinyint(1) NOT NULL COMMENT '그달 이 카드 실적 부족 알림 멈춤 여부; 되돌리면 false',
  `decided_at` timestamp(6) NOT NULL COMMENT 'UTC 마지막으로 판단·되돌린 시각',
  `created_at` timestamp(6) NOT NULL COMMENT 'UTC 생성 시각',
  `updated_at` timestamp(6) NOT NULL COMMENT 'UTC 수정 시각',
  `version` bigint NOT NULL DEFAULT '0' COMMENT 'JPA 낙관적 락 버전',
  PRIMARY KEY (`performance_decision_id`),
  UNIQUE KEY `uk_performance_decision_card_month` (`user_card_id`,`performance_month`),
  KEY `ix_performance_decision_owner` (`user_id`,`performance_month`),
  KEY `fk_performance_decision_card_owner` (`user_card_id`,`user_id`),
  CONSTRAINT `fk_performance_decision_card_owner` FOREIGN KEY (`user_card_id`, `user_id`) REFERENCES `user_card` (`user_card_id`, `user_id`) ON DELETE CASCADE,
  CONSTRAINT `ck_performance_decision_month` CHECK ((dayofmonth(`performance_month`) = 1)),
  CONSTRAINT `ck_performance_decision_muted` CHECK (((`decision` is not null) or (`notifications_muted` = false))),
  CONSTRAINT `ck_performance_decision_value` CHECK (((`decision` is null) or (`decision` in (_utf8mb4'FILL',_utf8mb4'KEEP',_utf8mb4'SKIP')))),
  CONSTRAINT `ck_performance_decision_version` CHECK ((`version` >= 0))
) ENGINE=InnoDB AUTO_INCREMENT=7 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin COMMENT='실적 유불리 판단 기록(카드·월당 한 줄)';
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `performance_decision`
--

