DROP TABLE IF EXISTS `step_up_audit_log`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `step_up_audit_log` (
  `step_up_audit_log_id` bigint NOT NULL AUTO_INCREMENT COMMENT '인증 기록 번호',
  `user_id` bigint NOT NULL COMMENT '인증 사용자',
  `user_device_id` bigint NOT NULL COMMENT '인증 기기; 필수',
  `auth_method` varchar(16) COLLATE utf8mb4_0900_bin NOT NULL COMMENT 'PIN / BIOMETRIC',
  `purpose` varchar(32) COLLATE utf8mb4_0900_bin NOT NULL COMMENT 'LOGIN / APP_UNLOCK / BARCODE / ACCOUNT_LINK 등; 인증 명세 코드',
  `result` varchar(16) COLLATE utf8mb4_0900_bin NOT NULL COMMENT 'SUCCESS / FAILURE',
  `fail_reason` varchar(100) COLLATE utf8mb4_0900_bin DEFAULT NULL COMMENT '원문 없이 저장하는 실패 코드',
  `challenge_id` varchar(128) CHARACTER SET ascii COLLATE ascii_bin DEFAULT NULL COMMENT '추적 식별자; challenge 원문 아님',
  `ip_address` varchar(45) CHARACTER SET ascii COLLATE ascii_general_ci DEFAULT NULL COMMENT 'IPv4 또는 IPv6 문자열',
  `user_agent` varchar(512) COLLATE utf8mb4_0900_bin DEFAULT NULL COMMENT '민감값을 제거한 요청 클라이언트 정보',
  `created_at` timestamp(6) NOT NULL COMMENT 'UTC 생성 시각',
  PRIMARY KEY (`step_up_audit_log_id`),
  UNIQUE KEY `uk_audit_owner` (`step_up_audit_log_id`,`user_id`),
  KEY `ix_audit_user_time` (`user_id`,`created_at`),
  KEY `ix_audit_device_owner` (`user_device_id`,`user_id`),
  CONSTRAINT `fk_audit_device_owner` FOREIGN KEY (`user_device_id`, `user_id`) REFERENCES `user_device` (`user_device_id`, `user_id`),
  CONSTRAINT `ck_audit_failure` CHECK (((`result` <> _utf8mb4'SUCCESS') or (`fail_reason` is null))),
  CONSTRAINT `ck_audit_method` CHECK ((`auth_method` in (_utf8mb4'PIN',_utf8mb4'BIOMETRIC'))),
  CONSTRAINT `ck_audit_result` CHECK ((`result` in (_utf8mb4'SUCCESS',_utf8mb4'FAILURE')))
) ENGINE=InnoDB AUTO_INCREMENT=298 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin COMMENT='추가 인증 이력';
