--
-- Table structure for table `tier_limit`
--

DROP TABLE IF EXISTS `tier_limit`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `tier_limit` (
  `tier_limit_id` bigint NOT NULL AUTO_INCREMENT COMMENT '실적 구간 한도 번호',
  `limit_group_id` bigint NOT NULL COMMENT '한도 그룹 버전',
  `min_performance_amount` bigint NOT NULL COMMENT '실적 하한; 포함',
  `max_performance_amount` bigint DEFAULT NULL COMMENT '실적 상한; 미포함, NULL 무제한',
  `limit_value` bigint NOT NULL COMMENT '한도값; 단위는 한도 그룹을 따름',
  `created_at` timestamp(6) NOT NULL COMMENT 'UTC 생성 시각',
  PRIMARY KEY (`tier_limit_id`),
  UNIQUE KEY `uk_tier_lower` (`limit_group_id`,`min_performance_amount`),
  CONSTRAINT `fk_tier_group` FOREIGN KEY (`limit_group_id`) REFERENCES `limit_group` (`limit_group_id`),
  CONSTRAINT `ck_tier_range` CHECK (((`min_performance_amount` >= 0) and ((`max_performance_amount` is null) or (`max_performance_amount` > `min_performance_amount`)))),
  CONSTRAINT `ck_tier_value` CHECK ((`limit_value` >= 0))
) ENGINE=InnoDB AUTO_INCREMENT=86 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin COMMENT='실적 구간별 한도';
/*!40101 SET character_set_client = @saved_cs_client */;

