--
-- Table structure for table `user_card`
--

DROP TABLE IF EXISTS `user_card`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `user_card` (
  `user_card_id` bigint NOT NULL AUTO_INCREMENT COMMENT '보유 카드 번호',
  `user_id` bigint NOT NULL COMMENT '보유 사용자',
  `card_product_id` bigint NOT NULL COMMENT '카드 상품',
  `linked_account_id` bigint DEFAULT NULL COMMENT '출금 계좌; 같은 사용자 소유',
  `issuer_account_bank_code` varchar(20) CHARACTER SET ascii COLLATE ascii_general_ci DEFAULT NULL COMMENT '카드사(시드)가 정한 출금·결제 계좌의 금융망 은행 코드; 등록 때 연결 계좌와 대조',
  `issuer_account_hash` binary(32) DEFAULT NULL COMMENT '카드사가 정한 계좌의 조회용 keyed HMAC(linked_account.account_no_hash와 같은 방식); 원문 저장 안 함',
  `issuer_account_last4` char(4) CHARACTER SET ascii COLLATE ascii_general_ci DEFAULT NULL COMMENT '카드사가 정한 계좌번호 끝 4자리(화면 표시용)',
  `card_no_enc` varbinary(2048) NOT NULL COMMENT '모의 카드번호 암호화 봉투; CVC 저장 금지',
  `card_no_hash` binary(32) NOT NULL COMMENT '카드번호 조회·중복 방지용 keyed HMAC',
  `card_last4` char(4) CHARACTER SET ascii COLLATE ascii_general_ci NOT NULL COMMENT '마스킹 표시용 마지막 네 자리',
  `card_alias` varchar(100) COLLATE utf8mb4_0900_bin DEFAULT NULL COMMENT '사용자 카드 별칭',
  `payment_day` smallint DEFAULT NULL COMMENT '월 결제일; 신용카드에 사용',
  `status` varchar(20) COLLATE utf8mb4_0900_bin NOT NULL COMMENT 'YAMU 등록 상태: PENDING 등록 전 / ACTIVE 추천·결제 사용 / INACTIVE 추천 제외 / UNREGISTERED 등록 해제; 카드사 상태는 issuer_status',
  `issuer_status` varchar(20) COLLATE utf8mb4_0900_bin NOT NULL DEFAULT 'NORMAL' COMMENT '카드사(발급사)가 정한 상태: NORMAL 정상 / SUSPENDED 정지 / EXPIRED 유효기간 만료; YAMU 등록 상태는 status',
  `registered_at` timestamp(6) NULL DEFAULT NULL COMMENT 'UTC 최초 사용자 등록 시각; 등록 전 PENDING 카드는 NULL',
  `display_order` int DEFAULT NULL COMMENT '보유 카드 목록 표시 순서(작을수록 앞)이자 추천 동률의 마지막 기준; 저장 전 NULL은 등록 순',
  `is_default` tinyint(1) NOT NULL DEFAULT '0' COMMENT '기본 카드 여부(순혜택이 같을 때만 우선); 사용자당 최대 1장, 등록된 카드만',
  `default_owner_id` bigint GENERATED ALWAYS AS ((case when (`is_default` = 1) then `user_id` end)) STORED COMMENT '기본 카드면 user_id, 아니면 NULL; 사용자당 기본 카드 1장 UNIQUE용 생성 칼럼',
  `payment_day_changed_at` timestamp(6) NULL DEFAULT NULL COMMENT 'UTC 마지막 결제일 변경 시각; 3개월 재변경 제한 기준, 등록 때 정한 결제일은 NULL',
  `created_at` timestamp(6) NOT NULL COMMENT 'UTC 생성 시각',
  `updated_at` timestamp(6) NOT NULL COMMENT 'UTC 수정 시각',
  `version` bigint NOT NULL DEFAULT '0' COMMENT 'JPA 낙관적 락 버전',
  `issuer_registered_on` date DEFAULT NULL,
  `ibk_context_month` date DEFAULT NULL,
  `ibk_salary_qualified` tinyint(1) DEFAULT NULL,
  `ibk_military_qualified` tinyint(1) DEFAULT NULL,
  PRIMARY KEY (`user_card_id`),
  UNIQUE KEY `uk_card_number` (`user_id`,`card_no_hash`),
  UNIQUE KEY `uk_card_owner` (`user_card_id`,`user_id`),
  UNIQUE KEY `uk_card_product` (`user_card_id`,`card_product_id`),
  UNIQUE KEY `uk_card_owner_product` (`user_card_id`,`user_id`,`card_product_id`),
  UNIQUE KEY `uk_card_default_owner` (`default_owner_id`),
  KEY `ix_card_account_owner` (`linked_account_id`,`user_id`),
  KEY `fk_card_product` (`card_product_id`),
  CONSTRAINT `fk_card_account_owner` FOREIGN KEY (`linked_account_id`, `user_id`) REFERENCES `linked_account` (`linked_account_id`, `user_id`),
  CONSTRAINT `fk_card_product` FOREIGN KEY (`card_product_id`) REFERENCES `card_product` (`card_product_id`),
  CONSTRAINT `fk_card_user` FOREIGN KEY (`user_id`) REFERENCES `app_user` (`user_id`),
  CONSTRAINT `ck_card_day` CHECK (((`payment_day` is null) or (`payment_day` between 1 and 31))),
  CONSTRAINT `ck_card_default_flag` CHECK ((`is_default` in (0,1))),
  CONSTRAINT `ck_card_default_registered` CHECK (((`is_default` = 0) or (`status` in (_utf8mb4'ACTIVE',_utf8mb4'INACTIVE')))),
  CONSTRAINT `ck_card_display_order` CHECK (((`display_order` is null) or (`display_order` >= 0))),
  CONSTRAINT `ck_card_issuer_account` CHECK ((((`issuer_account_bank_code` is null) and (`issuer_account_hash` is null) and (`issuer_account_last4` is null)) or ((`issuer_account_bank_code` is not null) and (`issuer_account_hash` is not null) and (`issuer_account_last4` is not null)))),
  CONSTRAINT `ck_card_issuer_status` CHECK ((`issuer_status` in (_utf8mb4'NORMAL',_utf8mb4'SUSPENDED',_utf8mb4'EXPIRED'))),
  CONSTRAINT `ck_ibk_context_fields` CHECK ((((`ibk_context_month` is null) and (`ibk_salary_qualified` is null) and (`ibk_military_qualified` is null)) or (`ibk_context_month` is not null))),
  CONSTRAINT `ck_ibk_context_month` CHECK (((`ibk_context_month` is null) or (dayofmonth(`ibk_context_month`) = 1))),
  CONSTRAINT `ck_user_card_version` CHECK ((`version` >= 0))
) ENGINE=InnoDB AUTO_INCREMENT=62 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin COMMENT='사용자 보유 카드';
/*!40101 SET character_set_client = @saved_cs_client */;

