--
-- Table structure for table `user_device`
--

DROP TABLE IF EXISTS `user_device`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `user_device` (
  `user_device_id` bigint NOT NULL AUTO_INCREMENT COMMENT '등록 기기 번호',
  `user_id` bigint NOT NULL COMMENT '기기 소유 사용자',
  `device_uuid` char(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT '기기 등록 UUID',
  `device_name` varchar(100) COLLATE utf8mb4_0900_bin DEFAULT NULL COMMENT '사용자에게 표시할 기기명',
  `platform` varchar(20) COLLATE utf8mb4_0900_bin NOT NULL COMMENT '기기 운영체제; 현재 Android만 지원하므로 ANDROID 저장',
  `public_key` text COLLATE utf8mb4_0900_bin NOT NULL COMMENT '현재 서명 검증용 공개키; PIN 전용 포함 모든 기기 필수',
  `key_algorithm` varchar(32) COLLATE utf8mb4_0900_bin NOT NULL COMMENT '서명 검증 알고리즘; 모든 기기 필수',
  `biometric_public_key` text COLLATE utf8mb4_0900_bin COMMENT '생체 로그인 서명 검증용 공개키(지문 인증이 필요한 키); 생체 사용 시 필수, 지문 재등록 시 교체',
  `biometric_enabled` tinyint(1) NOT NULL DEFAULT '0' COMMENT '생체인증 사용 동의·설정',
  `status` varchar(16) COLLATE utf8mb4_0900_bin NOT NULL DEFAULT 'ACTIVE' COMMENT 'ACTIVE / LOCKED / REVOKED',
  `failed_count` int NOT NULL DEFAULT '0' COMMENT '연속 인증 실패 횟수',
  `locked_until` timestamp(6) NULL DEFAULT NULL COMMENT 'UTC 잠금 해제 예정 시각',
  `last_verified_at` timestamp(6) NULL DEFAULT NULL COMMENT 'UTC 마지막 인증 성공 시각',
  `created_at` timestamp(6) NOT NULL COMMENT 'UTC 생성 시각',
  `updated_at` timestamp(6) NOT NULL COMMENT 'UTC 수정 시각',
  `version` bigint NOT NULL DEFAULT '0' COMMENT 'JPA 낙관적 락 버전',
  PRIMARY KEY (`user_device_id`),
  UNIQUE KEY `uk_device_owner_uuid` (`user_id`,`device_uuid`),
  UNIQUE KEY `uk_device_owner` (`user_device_id`,`user_id`),
  CONSTRAINT `fk_device_user` FOREIGN KEY (`user_id`) REFERENCES `app_user` (`user_id`),
  CONSTRAINT `ck_device_biometric` CHECK (((`biometric_enabled` in (0,1)) and ((`biometric_enabled` = 0) or (`biometric_public_key` is not null)))),
  CONSTRAINT `ck_device_failed` CHECK ((`failed_count` >= 0)),
  CONSTRAINT `ck_device_status` CHECK ((`status` in (_utf8mb4'ACTIVE',_utf8mb4'LOCKED',_utf8mb4'REVOKED'))),
  CONSTRAINT `ck_user_device_version` CHECK ((`version` >= 0))
) ENGINE=InnoDB AUTO_INCREMENT=40 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin COMMENT='등록 기기';
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `user_device`
--

LOCK TABLES `user_device` WRITE;
