DROP TABLE IF EXISTS `user_device_event`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `user_device_event` (
  `user_device_event_id` bigint NOT NULL AUTO_INCREMENT COMMENT '기기 이벤트 번호',
  `user_device_id` bigint NOT NULL COMMENT '이벤트 대상 기기',
  `event_type` varchar(32) COLLATE utf8mb4_0900_bin NOT NULL COMMENT '등록·키 교체·잠금·해제 등 이벤트 코드',
  `reason` varchar(255) COLLATE utf8mb4_0900_bin DEFAULT NULL COMMENT '민감값을 제거한 변경 사유',
  `created_at` timestamp(6) NOT NULL COMMENT 'UTC 생성 시각',
  PRIMARY KEY (`user_device_event_id`),
  KEY `ix_device_event_time` (`user_device_id`,`created_at`),
  CONSTRAINT `fk_device_event_device` FOREIGN KEY (`user_device_id`) REFERENCES `user_device` (`user_device_id`)
) ENGINE=InnoDB AUTO_INCREMENT=75 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin COMMENT='기기 변경 이력';
/*!40101 SET character_set_client = @saved_cs_client */;

